import React, { useState, useEffect, useRef } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/common/Navbar';
import Footer from './components/common/Footer';
import HeroSection from './components/home/HeroSection';
import DestinationGrid from './components/home/DestinationGrid';
import CurationSection from './components/home/CurationSection';
import MegaboxGuide from './components/home/MegaboxGuide';
import Carousel3D from './components/Carousel3D';
import SchedulePage from './pages/SchedulePage';
import { getLatestMovies } from './api/tmdb';
import './App.css';

function Home({ movies, currentIndex, setCurrentIndex }) {
  const currentMovie = movies[currentIndex] || movies[0] || null;

  return (
    <>
      <HeroSection currentMovie={currentMovie} />
      <Carousel3D movies={movies} currentIndex={currentIndex} setCurrentIndex={setCurrentIndex} />
      <DestinationGrid movies={movies} />
      <CurationSection />
      <MegaboxGuide />
    </>
  );
}

function App() {
  const [movies, setMovies] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  
  // 💡 관성 부드러운 스크롤을 위한 변수 관리 (Ref)
  const scrollRef = useRef({
    current: 0,
    target: 0,
    ease: 0.08, // 숫자가 낮을수록 더 부드럽고 묵직하게 미끄러짐 (0.05 ~ 0.1 추천)
  });

  useEffect(() => {
    const fetchMovies = async () => {
      const data = await getLatestMovies();
      if (data && data.length > 0) {
        setMovies(data);
      }
    };
    fetchMovies();
  }, []);

  // 💡 레퍼런스 같은 묵직하고 부드러운 관성 스크롤 엔진 실행
  useEffect(() => {
    let animationFrameId;

    const handleWheel = (e) => {
      e.preventDefault(); // 기본 뚝뚝 끊기는 스크롤 차단
      
      // 타겟 스크롤 위치 계산 (최대 스크롤 범위를 넘지 않도록 제한)
      const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
      scrollRef.current.target += e.deltaY * 0.8; // 스크롤 감도 조절
      scrollRef.current.target = Math.max(0, Math.min(scrollRef.current.target, maxScroll));
    };

    // 부드럽게 따라붙는 애니메이션 루프 (Lerp 방식)
    const smoothScrollLoop = () => {
      const { current, target, ease } = scrollRef.current;
      
      // 현재 위치에서 타겟 위치로 부드럽게 보간(Lerp)
      scrollRef.current.current += (target - current) * ease;
      
      window.scrollTo(0, scrollRef.current.current);
      animationFrameId = requestAnimationFrame(smoothScrollLoop);
    };

    // 초기 스크롤 위치 동기화
    scrollRef.current.target = window.scrollY;
    scrollRef.current.current = window.scrollY;

    window.addEventListener('wheel', handleWheel, { passive: false });
    animationFrameId = requestAnimationFrame(smoothScrollLoop);

    return () => {
      window.removeEventListener('wheel', handleWheel);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <Router>
      <div className="bg-[#0b090e] min-h-screen text-white font-sans flex flex-col justify-between selection:bg-purple-500 selection:text-white">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route 
              path="/" 
              element={
                <Home 
                  movies={movies} 
                  currentIndex={currentIndex} 
                  setCurrentIndex={setCurrentIndex} 
                />
              } 
            />
            <Route path="/schedule" element={<SchedulePage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
